nilai = int(input("Masukkan nilai (0-100): "))

if nilai >= 90:
    print("Nilai A - Sempurna!")
elif nilai >= 75:
    print("Nilai B - Bagus!")
elif nilai >= 60:
    print("Nilai C - Cukup")
else:
    print("Nilai D - Perlu belajar lebih giat")

# For loop dengan range
for i in range(1, 6):
    print(f"Bintang ke-{i}: " + "*" * i)

# While loop
hitung = 10
while hitung > 0:
    print(hitung)
    hitung -= 2
print("Selesai!")

# Break dan continue
for angka in range(10):
    if angka == 3:
        continue  # Lewati angka 3
    if angka == 7:
        break     # Berhenti di angka 7
    print(angka)

def bagi_angka(a, b):
    try:
        hasil = a / b
    except ZeroDivisionError:
        print("Error: Tidak bisa dibagi nol!")
        return None
    except TypeError:
        print("Error: Input harus berupa angka!")
        return None
    else:
        print(f"{a} / {b} = {hasil}")
        return hasil
    finally:
        print("Proses pembagian selesai.")

bagi_angka(10, 2)   # Berhasil
bagi_angka(5, 0)    # ZeroDivisionError

import json
import os

class TodoApp:
    def __init__(self, file_name="todos.json"):
        self.file_name = file_name
        self.todos = self.muat_data()

    def muat_data(self):
        if os.path.exists(self.file_name):
            with open(self.file_name, "r") as f:
                return json.load(f)
        return []

    def simpan_data(self):
        with open(self.file_name, "w") as f:
            json.dump(self.todos, f, indent=2)

    def tambah(self, tugas):
        self.todos.append({"tugas": tugas, "selesai": False})
        self.simpan_data()
        print(f"Ditambahkan: {tugas}")

    def tampilkan(self):
        for i, todo in enumerate(self.todos, 1):
            status = "✓" if todo["selesai"] else "○"
            print(f"{i}. [{status}] {todo['tugas']}")

app = TodoApp()
app.tambah("Belajar Python")
app.tampilkan()
